model Task {
  id: ID
  title: String
  done: Bool = false
}

component TaskItem(task: Task, onDelete: Fn, onToggle: Fn) {
  row gap=2 align=center pad=2 {
    checkbox task.done -> onToggle()
    text task.title muted=task.done
    button "x" danger small -> onDelete()
  }
}

page Todos "/" {
  state newTask = ""
  state tasks: Task[] = []

  fn addTask() {
    if newTask.trim() == "" { return }
    tasks.push({ id: crypto.randomUUID(), title: newTask, done: false })
    newTask = ""
  }

  fn deleteTask(id) {
    tasks = tasks.filter(t => t.id != id)
  }

  fn toggleTask(id) {
    let task = tasks.find(t => t.id == id)
    if task { task.done = !task.done }
  }

  computed pending = tasks.filter(t => !t.done).length

  column gap=4 pad=4 align=center {
    title "Mis Tareas"
    row gap=2 {
      input newTask placeholder="¿Qué hay que hacer?" -> addTask()
      button "Agregar" primary -> addTask()
    }
    column gap=2 {
      for t in tasks {
        TaskItem task=t onDelete=(() => deleteTask(t.id)) onToggle=(() => toggleTask(t.id))
      }
    }
    if tasks.length == 0 {
      text "No hay tareas" muted
    } else {
      text `${pending} pendientes` muted
    }
  }
}

