model Product {
  id: ID
  name: String
  price: Number
}

model CartItem {
  product: Product
  quantity: Number
}

component App {
  state products: Product[] = [
    { id: "1", name: "Laptop", price: 999.99 }
    { id: "2", name: "Mouse", price: 29.99 }
    { id: "3", name: "Keyboard", price: 79.99 }
  ]

  state cart: CartItem[] = []

  computed total = cart.reduce((sum, item) => sum + (item.product.price * item.quantity), 0)

  fn addToCart(product) {
    let existing = cart.find(item => item.product.id == product.id)
    if existing {
      existing.quantity++
    } else {
      cart.push({ product: product, quantity: 1 })
    }
  }

  fn removeFromCart(productId) {
    cart = cart.filter(item => item.product.id != productId)
  }

  fn updateQuantity(productId, delta) {
    let item = cart.find(i => i.product.id == productId)
    if item {
      item.quantity += delta
      if item.quantity <= 0 {
        removeFromCart(productId)
      }
    }
  }

  row gap=6 {
    column gap=4 pad=4 {
      title "Productos"
      for p in products {
        card pad=3 {
          row justify=between align=center {
            column gap=2 {
              text p.name bold
              text `$${p.price.toFixed(2)}` muted
            }
            button "Agregar" primary -> addToCart(p)
          }
        }
      }
    }

    column gap=4 pad=4 {
      title "Carrito"
      if cart.length == 0 {
        text "Vacío" muted
      } else {
        for item in cart {
          card pad=3 {
            row justify=between align=center {
              column gap=1 {
                text item.product.name
                text `$${(item.product.price * item.quantity).toFixed(2)}` muted small
              }
              row gap=2 align=center {
                button "-" -> updateQuantity(item.product.id, -1)
                text item.quantity
                button "+" -> updateQuantity(item.product.id, 1)
                button "×" danger -> removeFromCart(item.product.id)
              }
            }
          }
        }
        divider
        row justify=between align=center pad=3 {
          title "Total" small
          title `$${total.toFixed(2)}` small
        }
      }
    }
  }
}

