page Shop "/shop" {
  state products: Product[] = [
    { id: "1", name: "Laptop", price: 999.99 }
    { id: "2", name: "Mouse", price: 29.99 }
    { id: "3", name: "Teclado", price: 79.99 }
  ]

  state cart: CartItem[] = []

  computed total = cart.reduce((sum, item) => sum + (item.price * item.quantity), 0)

  fn addToCart(product) {
    let existing = cart.find(item => item.productId == product.id)
    if existing {
      existing.quantity++
    } else {
      cart.push({ productId: product.id, name: product.name, price: product.price, quantity: 1 })
    }
  }

  fn increaseQuantity(productId) {
    let item = cart.find(i => i.productId == productId)
    if item {
      item.quantity++
    }
  }

  fn decreaseQuantity(productId) {
    let item = cart.find(i => i.productId == productId)
    if item {
      item.quantity--
      if item.quantity == 0 {
        cart = cart.filter(i => i.productId != productId)
      }
    }
  }

  column gap=6 pad=4 {
    row gap=8 {
      column gap=4 {
        title "Productos"
        column gap=3 {
          for p in products {
            card pad=3 {
              ProductCard product=p onAdd=(() => addToCart(p))
            }
          }
        }
      }

      column gap=4 {
        title "Carrito"
        if cart.length == 0 {
          text "Carrito vacío" muted
        } else {
          column gap=3 {
            for item in cart {
              card pad=3 {
                CartItemRow item=item onIncrease=(() => increaseQuantity(item.productId)) onDecrease=(() => decreaseQuantity(item.productId))
              }
            }
          }
        }
        divider
        row gap=2 justify=between {
          text "Total:" bold large
          text `$${total.toFixed(2)}` bold large primary
        }
      }
    }
  }
}

