page Users "/users" {
  state name = ""
  state email = ""
  state emailError = ""

  data users = api.users.list()

  fn validateEmail(e) {
    if !e.includes("@") {
      emailError = "Email inválido"
      return false
    }
    emailError = ""
    return true
  }

  fn addUser() {
    if !validateEmail(email) { return }
    if name.trim() == "" { return }

    try {
      api.users.create({ name, email })
      name = ""
      email = ""
      users.reload()
    } catch (e) {
      emailError = e.message
    }
  }

  fn deleteUser(id) {
    try {
      api.users.remove(id)
      users.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=4 pad=4 {
    title "Usuarios"

    card gap=3 pad=3 {
      input name placeholder="Nombre"
      input email placeholder="Email"
      if emailError != "" {
        text emailError danger small
      }
      button "Agregar" primary -> addUser()
    }

    if users.loading {
      spinner
    } else if users.length == 0 {
      text "No hay usuarios" muted
    } else {
      for u in users key u.id {
        card {
          UserItem user=u onDelete=(id => deleteUser(id))
        }
      }
    }
  }
}

