page Home "/" {
  state authorName = ""
  state postTitle = ""
  state selectedAuthorId: String?

  data authors = api.authors.list()
  data posts = api.posts.list({ include: ["post.author"] }) live

  fn createAuthor() {
    if authorName.trim() == "" { return }
    try {
      api.authors.create({ name: authorName })
      authorName = ""
      authors.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn publishPost() {
    if postTitle.trim() == "" { return }
    if !selectedAuthorId { return }
    try {
      api.posts.create({ title: postTitle, author: selectedAuthorId })
      postTitle = ""
      selectedAuthorId = null
      posts.reload()
      authors.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn deleteAuthor(id: String) {
    try {
      api.authors.remove(id)
      authors.reload()
      posts.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  column gap=6 pad=4 {
    title "Blog"

    card {
      title "Crear Autor" small
      row gap=2 {
        input authorName placeholder="Autor"
        button "Crear autor" primary -> createAuthor()
      }
    }

    card {
      title "Publicar Post" small
      column gap=2 {
        input postTitle placeholder="Título"
        select selectedAuthorId placeholder="Elegir autor" options=(authors.map(a => ({ value: a.id, label: a.name })))
        button "Publicar" primary -> publishPost()
      }
    }

    card {
      title "Autores" small
      if authors.length == 0 {
        text "No hay autores" muted
      } else {
        column gap=2 {
          for author in authors {
            row gap=2 align=center justify=between {
              text author.name
              button "Borrar" danger small -> {
                let postCount = posts.filter(p => p.author.id == author.id).length
                if postCount > 0 {
                  notify("El autor tiene posts", "danger")
                } else {
                  deleteAuthor(author.id)
                }
              }
            }
          }
        }
      }
    }

    card {
      title "Posts" small
      if posts.length == 0 {
        text "No hay posts" muted
      } else {
        column gap=2 {
          for post in posts {
            card {
              title post.title small
              text `por ${post.author.name}` muted small
            }
          }
        }
      }
    }
  }
}

