  computed startIndex = (page - 1) * itemsPerPage
  computed endIndex = startIndex + itemsPerPage
  computed currentItems = items.slice(startIndex, endIndex)

  column gap=4 pad=4 {
    title "Lista de Ítems"

    for item in currentItems {
      text item
    }

    row gap=4 align=center {
      text `Página ${page} de ${totalPages}`
      button "Anterior" disabled=(page == 1) -> page = page - 1
      button "Siguiente" disabled=(page == totalPages) -> page = page + 1
    }
  }
}

