model Employee {
  id: ID
  name: String
  age: Number
}

page Employees "/employees" {
  state employees: Employee[] = [
    { id: "1", name: "Caro", age: 35 }
    { id: "2", name: "Ana", age: 30 }
    { id: "3", name: "Dani", age: 28 }
    { id: "4", name: "Beto", age: 25 }
  ]

  state sortBy = "none"
  state filterText = ""

  computed filtered = employees.filter(e =>
    e.name.toLowerCase().includes(filterText.toLowerCase())
  )

  computed sorted = (() => {
    let result = [...filtered]
    if sortBy == "name" {
      result.sort((a, b) => a.name.localeCompare(b.name))
    } else if sortBy == "age" {
      result.sort((a, b) => a.age - b.age)
    }
    return result
  })()

  column gap=4 {
    title "Empleados"

    row gap=2 {
      button "Ordenar por nombre" -> sortBy = sortBy == "name" ? "none" : "name"
      button "Ordenar por edad" -> sortBy = sortBy == "age" ? "none" : "age"
    }

    input filterText placeholder="Filtrar"

    table {
      tr {
        th "Nombre"
        th "Edad"
      }
      for e in sorted {
        tr {
          td e.name
          td `${e.age}`
        }
      }
    }

    text `Empleados: ${sorted.length}`
  }
}

