model Task {
  id: ID
  title: String
  done: Bool = false
}

api tasks: Task

page Tasks "/tasks" {
  state filter = "all"
  state newTaskTitle = ""
  state editingId: ID? = null
  state editingTitle = ""

  data visibleTasks = api.tasks.list({
    where: filter == "all" ? {} : filter == "done" ? { done: true } : { done: false }
  })

  fn addTask() {
    if newTaskTitle.trim() == "" { return }
    await api.tasks.create({ title: newTaskTitle, done: false })
    newTaskTitle = ""
  }

  fn markDone(id) {
    await api.tasks.update(id, { done: true })
  }

  fn startEditing(task) {
    editingId = task.id
    editingTitle = task.title
  }

  fn cancelEditing() {
    editingId = null
    editingTitle = ""
  }

  fn saveTitle(id) {
    if editingTitle.trim() == "" { return }
    await api.tasks.update(id, { title: editingTitle })
    editingId = null
    editingTitle = ""
  }

  column gap=4 pad=4 {
    title "Gestor de Tareas"

    row gap=2 {
      input newTaskTitle placeholder="Tarea"
      button "Agregar" primary -> addTask()
    }

    select filter placeholder="Filtrar" options=[
      { value: "all", label: "Todas" }
      { value: "pending", label: "Pendientes" }
      { value: "done", label: "Hechas" }
    ]

    if visibleTasks.loading {
      spinner
    } else if visibleTasks.error {
      text visibleTasks.error danger
    } else if visibleTasks.length == 0 {
      text "No hay tareas" muted
    } else {
      column gap=2 {
        for task in visibleTasks key task.id {
          row gap=2 align=center pad=3 {
            if editingId == task.id {
              input editingTitle placeholder="Nuevo título"
              button "Guardar" primary -> saveTitle(task.id)
              button "Cancelar" -> cancelEditing()
            } else {
              column {
                text `${task.title}${task.done ? " (hecha)" : ""}` muted=task.done
              }
              if !task.done {
                button "Hecha" -> markDone(task.id)
              }
              button "Renombrar" -> startEditing(task)
            }
          }
        }
      }
    }
  }
}

model Task {
  id: ID
  title: String min=1 max=100
