model Product {
  id: ID
  name: String min=1
}

api products: Product

component ProductCard(product: Product) {
  card {
    text product.name
  }
}

page Catalog "/catalog" {
  state search = ""
  state page = 1

  data products = api.products.list({
    search: search,
    limit: 5,
    offset: (page - 1) * 5,
    sort: "name"
  })

  data total = api.products.count({ search: search })

  fn loadExamples() {
    try {
      server.createExamplesIfEmpty()
      products.reload()
      total.reload()
    } catch (e) {
      notify(e.message, "danger")
    }
  }

  fn onSearch(q) {
    search = q
    page = 1
  }

  fn goToPrevious() {
    if page > 1 {
      page--
    }
  }

  fn goToNext() {
    if page * 5 < total {
      page++
    }
  }

  column gap=4 pad=4 {
    row gap=2 align=center {
      title "Catálogo"
      button "Cargar ejemplos" -> loadExamples()
    }
    input search placeholder="Buscar" -> onSearch(search)
    text `Total: ${total}` muted
    if products.loading {
      spinner
    } else if products.error {
      text products.error danger
    } else {
      column gap=2 {
        for product in products {
          ProductCard product=product
        }
      }
      row gap=2 justify=center {
        button "Anterior" disabled=(page <= 1) -> goToPrevious()
        text `Página ${page}`
        button "Siguiente" disabled=(page * 5 >= total) -> goToNext()
      }
    }
  }
