  }
  if user[0].password != password {
    fail("Contraseña incorrecta", 401)
  }
}

server fn createNote(text) {
  if !me {
    fail("No autenticado", 401)
  }
  db.notes.create({ text, owner: me.id })
}

server fn deleteNote(id) {
  if !me {
    fail("No autenticado", 401)
  }
  let note = db.notes.get(id)
  if note.owner != me.id {
    fail("No autorizado", 403)
  }
  db.notes.remove(id)
}

server fn logout() {
  me = null
}

