  state amount = 0
  state error = ""
  fn submit() {
    if name.trim() == "" {
      error = "Nombre requerido"
    } else {
      onAdd(name, amount)
      name = ""
      amount = 0
      error = ""
    }
  }

  column gap=2 {
    if error != "" {
